WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Author" AS "Author", "Year", "Cancer type", "Trial phase", "Control arm"
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%gastric%' AND LOWER("Cancer type") LIKE '%gej%' AND "Trial phase" = 'Phase 3'
)
SELECT * FROM base;
